el van de reeks draait om de jacht op iemand die overleven tot een bron van schuld maakt.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.penguin.co.uk/books/213223/eeny-meeny-by-arlidge-m-j/9781405914871","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p399277528","http://data.bibliotheken.nl/id/nbt/p429986769"],"checked_at":"2026-11-03T12:39:49.425Z","reference":"work:1630","note":"ExactexistingDutchprintIenemienemutteISBN9789022576229, KBoriginalEenyMeeny2014 andprimaryPenguinDIHelenGrace1 confirms samebook. Correctoriginalyear2016to2014withoutchangingrankorseries.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-amendment-029.json","sources":["https://www.penguin.co.uk/books/213223/eeny-meeny-by-arlidge-m-j/9781405914871","https://data.bibliotheken.nl/id/nbt/p399277528","https://data.bibliotheken.nl/id/nbt/p429986769"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL45876799M","isbn13":"9789022576229","checkedAt":"2026-11-03T12:39:49.426Z","note":"Exact earliertransportfailure/unpublishedarchive retained, noretryorclaimofabsence. Actualhosteddecodedcoverorplaceholderseparatelyrequired.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15195307,"status":"bulk_archive_unavailable","receiptSha256":"01f189d7785da46ad38b728eded6972350e6dbc066a98d304fcd35be46e12f27"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-03T12:39:49.425Z","review_batch":"nl-scale-20261102-063"}},{"ref":"m1","relation":"catalog_edition_metadata","key":{"edition_id":987262001},"before":null,"after":{"edition_id":987262001,"work_id":987162001,"bound_author_id":9873